python - <<'PY'
import json, math
path='/app/answers.json'
with open(path) as f:answers=json.load(f)
assert set(answers)=={'q1','q2','q3','q4'}
for q in ['q1','q2']:
 assert set(answers[q])=={'lo','hi'}
 assert all(isinstance(v,(int,float)) and math.isfinite(v) for v in answers[q].values())
 assert answers[q]['lo']<=answers[q]['hi']
assert 0<=answers['q1']['lo']<=answers['q1']['hi']<=1
for q in ['q3','q4']:
 x=answers[q]
 assert x['verdict'] in ['entailed','refutable']
 if x['verdict']=='entailed':assert set(x)=={'verdict'}
 else:
  assert set(x)=={'verdict','witness'}
  w=x['witness'];assert set(w)=={'a','rho','rho_tail'}
  assert .8943<=w['a']<=.9547 and .9366<=w['rho']<=.9735 and .85<=w['rho_tail']<=1
print(open(path).read())
print('Validated all four answers.')
PY
